-- Thêm / sửa kết quả xét tốt nghiệp hệ sơ cấp (upsert theo StudentID + ExamDateID)

IF OBJECT_ID(N'[dbo].[SIM_GraduationResult_AddOrEdit_SoCap]', N'P') IS NOT NULL
    DROP PROCEDURE [dbo].[SIM_GraduationResult_AddOrEdit_SoCap]
GO

CREATE PROCEDURE [dbo].[SIM_GraduationResult_AddOrEdit_SoCap]
(
    @GraduationResultID bigint = null,
    @StudentID bigint,
    @ExamDateID int,
    @OrderExam int = 1,
    @YearID int = null,
    @SummaryLearningMark float = null,
    @SummaryLearningLevel nvarchar(50) = null,
    @GraduationExamAverage float = null,
    @GraduationRankingAverage float = null,
    @GraduationLevel nvarchar(50) = null,
    @DecisionNo nvarchar(50) = null,
    @Signingdate datetime = null,
    @Signer nvarchar(100) = null,
    @CerNo nvarchar(50) = null,
    @SavedCerNo nvarchar(50) = null,
    @CerIssued datetime = null,
    @ResultReview int = null,
    @SpecialType int = null,
    @CreatedUser nvarchar(50) = null,
    @UpdatedUser nvarchar(50) = null
)
AS
BEGIN
    SET NOCOUNT ON

    If @GraduationResultID Is Not Null And @GraduationResultID > 0
    Begin
        Update SIM_GraduationResult
        Set
            StudentID = @StudentID,
            ExamDateID = @ExamDateID,
            OrderExam = IsNull(@OrderExam, 1),
            YearID = @YearID,
            SummaryLearningMark = @SummaryLearningMark,
            SummaryLearningLevel = @SummaryLearningLevel,
            GraduationExamAverage = @GraduationExamAverage,
            GraduationRankingAverage = @GraduationRankingAverage,
            GraduationLevel = @GraduationLevel,
            DecisionNo = @DecisionNo,
            Signingdate = @Signingdate,
            Signer = @Signer,
            CerNo = @CerNo,
            SavedCerNo = @SavedCerNo,
            CerIssued = @CerIssued,
            ResultReview = @ResultReview,
            SpecialType = @SpecialType,
            UpdatedDate = GetDate(),
            UpdatedUser = @UpdatedUser
        Where GraduationResultID = @GraduationResultID
    End
    Else
    Begin
        Insert Into SIM_GraduationResult
        (
            StudentID,
            ExamDateID,
            OrderExam,
            HaveExamRegister1,
            HaveExamRegister2,
            HaveExamRegister3,
            YearID,
            SummaryLearningMark,
            SummaryLearningLevel,
            GraduationExamAverage,
            GraduationRankingAverage,
            GraduationLevel,
            DecisionNo,
            Signingdate,
            Signer,
            CerNo,
            SavedCerNo,
            CerIssued,
            ResultReview,
            SpecialType,
            CreatedDate,
            CreatedUser
        )
        Values
        (
            @StudentID,
            @ExamDateID,
            IsNull(@OrderExam, 1),
            0,
            0,
            0,
            @YearID,
            @SummaryLearningMark,
            @SummaryLearningLevel,
            @GraduationExamAverage,
            @GraduationRankingAverage,
            @GraduationLevel,
            @DecisionNo,
            @Signingdate,
            @Signer,
            @CerNo,
            @SavedCerNo,
            @CerIssued,
            @ResultReview,
            @SpecialType,
            GetDate(),
            @CreatedUser
        )

        Set @GraduationResultID = SCOPE_IDENTITY()
    End

    Select @GraduationResultID As GraduationResultID
END
GO

