using System;
using System.Data;
using System.Drawing;
using System.Windows.Forms;
using Libs;
using Global;
using Service;
using SimsObject;
using DevExpress.XtraGrid.Views.BandedGrid;

namespace StudentManager.Graduation
{
    public partial class frmThongKeTotNghiep_V2 : FormBase, IForm
    {
        #region Consts

        public const string PERMISSION_EDIT = "ThongKeTotNghiep_V2_Edit";
        public const string PERMISSION_VIEW = "ThongKeTotNghiep_V2";
        private const string QUERY_NAME = "ThongKeTotNghiep_V2";
        private const string GRADUATION_BAND = "TỐT NGHIỆP";

        #endregion

        #region Variables

        bool bolIsRefresh = false;
        DataTable dtbData;
        int? intExamDateID = null;

        #endregion

        #region IForm Members

        private static frmThongKeTotNghiep_V2 _instance = null;

        public static frmThongKeTotNghiep_V2 Instance
        {
            get
            {
                if (_instance == null)
                    _instance = new frmThongKeTotNghiep_V2();
                return _instance;
            }
        }

        public void Run(bool isShowDialog)
        {
            FormManager.Run(Instance, isShowDialog);
        }

        #endregion

        public frmThongKeTotNghiep_V2()
        {
            InitializeComponent();
        }

        #region Support Functions

        private void CheckPermission()
        {
            btnXetTotNghiep.Enabled = UserSession.HasPermission(PERMISSION_EDIT);
            btnSave.Enabled = mnuItemSave.Enabled = false;
        }

        private bool IsValidExamDate()
        {
            if (uExamDateCheck.ExamDateIDEditValue == null || uExamDateCheck.ExamDateIDEditValue.ToString() == "")
            {
                MessageManager.Warning("Bạn phải chọn kỳ tốt nghiệp trước khi xét!");
                return false;
            }
            return true;
        }

        private bool HasGraduationData()
        {
            if (dtbData == null)
                return false;

            foreach (DataRow drw in dtbData.Rows)
            {
                if (drw["HasGraduationResult"].ToString() == "1")
                    return true;
            }
            return false;
        }

        public void LoadData()
        {
            if (!uExamDateCheck.IsValidData())
                return;

            intExamDateID = uExamDateCheck.ExamDateIDEditValueInt32;

            SIM_GraduationResult obj = new SIM_GraduationResult();
            dtbData = obj.GetDataTable(QUERY_NAME,
                                "@ScienceIDList", uScienceCourseTypeLevel.ScienceIDEditValue,
                                "@CourseIDList", uScienceCourseTypeLevel.CourseIDEditValue,
                                "@TrainingLevelIDList", uScienceCourseTypeLevel.TrainingLevelIDEditValue,
                                "@TrainingType", uScienceCourseTypeLevel.TrainingTypeEditValue,
                                "@ExamDateIDList", uExamDateCheck.ExamDateIDEditValue);

            if (dtbData != null)
            {
                gcData.DataSource = dtbData;
                SystemService.SYS_GridColumnService.InitGridColumn(gvData, QUERY_NAME, bolIsRefresh);
                ModifyGrid();

                mnuItemSave.Enabled = btnSave.Enabled = false;
                btnXetTotNghiep.Enabled = dtbData.Rows.Count > 0 && UserSession.HasPermission(PERMISSION_EDIT);
                mnuItemExportToExcel.Enabled = dtbData.Rows.Count > 0;
                bolIsRefresh = false;
            }
            else
            {
                ErrorManager.Error("Việc tải thông tin bị lỗi!");
            }
        }

        public void LoadReferenceData()
        {
            if (bolIsRefresh)
            {
                uExamDateCheck.RefrehData();
                uScienceCourseTypeLevel.RefrehData();
            }
            else
            {
                uExamDateCheck.InitData();
                uScienceCourseTypeLevel.InitData();
            }
        }

        private void ModifyGrid()
        {
            bool bolShowGraduation = HasGraduationData();

            foreach (BandedGridColumn col in gvData.Columns)
            {
                if (col.OwnerBand != null && col.OwnerBand.Caption == GRADUATION_BAND)
                {
                    col.Visible = bolShowGraduation;
                }
            }

            gvData.OptionsBehavior.Editable = bolShowGraduation && UserSession.HasPermission(PERMISSION_EDIT);
        }

        private void ReviewGraduation()
        {
            if (!IsValidExamDate())
                return;

            if (dtbData == null || dtbData.Rows.Count == 0)
            {
                MessageManager.Warning("Không có dữ liệu để xét!");
                return;
            }

            foreach (DataRow drw in dtbData.Rows)
            {
                double dblTBC = 0;
                bool bolPassed = false;
                if (drw["LearningSummary"].ToString() != "")
                {
                    dblTBC = Convert.ToDouble(drw["LearningSummary"]);
                    bolPassed = dblTBC > 5;
                }

                string strLearningLevel = drw["LearningLevel"].ToString();

                drw["SummaryLearningMark"] = drw["LearningSummary"].ToString() != "" ? (object)dblTBC : DBNull.Value;
                drw["SummaryLearningLevel"] = strLearningLevel != "" ? (object)strLearningLevel : DBNull.Value;
                drw["GraduationRankingAverage"] = drw["LearningSummary"].ToString() != "" ? (object)dblTBC : DBNull.Value;
                drw["GraduationExamAverage"] = drw["LearningSummary"].ToString() != "" ? (object)dblTBC : DBNull.Value;

                if (bolPassed)
                {
                    drw["GraduationLevel"] = strLearningLevel != "" ? (object)strLearningLevel : DBNull.Value;
                    drw["ResultReview"] = 1;
                }
                else
                {
                    drw["GraduationLevel"] = N"Không đạt";
                    drw["ResultReview"] = 0;
                }

                drw["ExamDateID"] = intExamDateID;
                drw["IsEdit"] = 1;
            }

            btnSave.Enabled = mnuItemSave.Enabled = true;
            MessageManager.Information("Đã xét tốt nghiệp theo TBC toàn khóa. Vui lòng bấm Lưu để ghi nhận kết quả.");
        }

        private bool Save()
        {
            if (!IsValidExamDate())
                return false;

            SIM_GraduationResult item = new SIM_GraduationResult();
            SIM_Student objStudent = new SIM_Student();
            item.BeginTransaction();
            objStudent.IDB = item.IDB;
            item.ExamDateID = intExamDateID;

            foreach (DataRow drw in dtbData.Rows)
            {
                if (drw["IsEdit"].ToString() != "1")
                    continue;

                item.GraduationResultID = drw["GraduationResultID"].ToString() != ""
                    ? Convert.ToInt64(drw["GraduationResultID"])
                    : (long?)null;
                item.StudentID = Convert.ToInt64(drw["StudentID"]);
                item.OrderExam = 1;

                if (drw["ResultReview"].ToString() == "")
                    item.ResultReview = null;
                else if (drw["ResultReview"].ToString() == "1")
                    item.ResultReview = 1;
                else
                    item.ResultReview = 0;

                item.SummaryLearningLevel = drw["SummaryLearningLevel"].ToString();
                item.GraduationLevel = drw["GraduationLevel"].ToString();

                if (drw["SummaryLearningMark"].ToString() != "")
                {
                    item.SummaryLearningMark = Convert.ToDouble(drw["SummaryLearningMark"]);
                    item.GraduationExamAverage = Convert.ToDouble(drw["SummaryLearningMark"]);
                    item.GraduationRankingAverage = Convert.ToDouble(drw["SummaryLearningMark"]);
                }
                else
                {
                    item.SummaryLearningMark = null;
                    item.GraduationExamAverage = null;
                    item.GraduationRankingAverage = null;
                }

                item.YearID = Libs.MyConvert.ToInt32(drw["YearID"]);
                item.DecisionNo = drw["DecisionNo"].ToString();
                item.CerNo = drw["CerNo"].ToString();
                item.SavedCerNo = drw["SavedCerNo"].ToString();

                if (drw["Signingdate"].ToString() != "")
                    item.Signingdate = Convert.ToDateTime(drw["Signingdate"]);
                else
                    item.Signingdate = null;

                if (drw["CerIssued"].ToString() != "")
                    item.CerIssued = Convert.ToDateTime(drw["CerIssued"]);
                else
                    item.CerIssued = null;

                if (drw["SpecialType"].ToString() != "")
                    item.SpecialType = Convert.ToInt32(drw["SpecialType"]);
                else
                    item.SpecialType = null;

                if (item.GraduationResultID != null)
                    item.UpdatedUser = UserSession.Username;
                else
                    item.CreatedUser = UserSession.Username;

                if (!item.AddOrEdit_SoCap())
                {
                    ErrorManager.Error("Việc lưu kết quả xét tốt nghiệp bị lỗi!");
                    return false;
                }

                if (item.ResultReview != null)
                {
                    if (item.ResultReview == 1)
                        objStudent.Status = 2;
                    else
                        objStudent.Status = 1;

                    objStudent.UpdatedUser = UserSession.Username;
                    objStudent.StudentID = Convert.ToInt32(drw["StudentID"]);
                    if (!objStudent.UpdateStatus())
                    {
                        ErrorManager.Error("Cập nhật trạng thái hồ sơ sinh viên thất bại!");
                        return false;
                    }
                }
            }

            item.CommitTransaction();
            return true;
        }

        #endregion

        #region Form Actions

        private void frmThongKeTotNghiep_V2_Load(object sender, EventArgs e)
        {
            LoadReferenceData();
            CheckPermission();
            SetToolTip();
        }

        private void btnClose_Click(object sender, EventArgs e)
        {
            this.Close();
        }

        private void btnSearch_Click(object sender, EventArgs e)
        {
            LoadData();
        }

        private void btnXetTotNghiep_Click(object sender, EventArgs e)
        {
            ReviewGraduation();
        }

        private void btnSave_Click(object sender, EventArgs e)
        {
            if (Save())
                LoadData();
        }

        private void mnuItemRefresh_Click(object sender, EventArgs e)
        {
            bolIsRefresh = true;
            LoadReferenceData();
            btnSearch_Click(null, null);
        }

        private void mnuItemExportToExcel_Click(object sender, EventArgs e)
        {
            gvData.QuickExportToExcel();
        }

        private void gvData_ValidateRow(object sender, DevExpress.XtraGrid.Views.Base.ValidateRowEventArgs e)
        {
            DataRow drw = gvData.GetFocusedDataRow();
            if (drw != null)
            {
                drw["IsEdit"] = 1;
                btnSave.Enabled = mnuItemSave.Enabled = true;
            }
        }

        private void gvData_RowCellStyle(object sender, DevExpress.XtraGrid.Views.Grid.RowCellStyleEventArgs e)
        {
            if (e.Column.FieldName == "GraduationLevel")
            {
                if (e.CellValue == null || e.CellValue.ToString() == "")
                    e.Appearance.BackColor = Color.Yellow;
                else if (e.CellValue.ToString() == "Không đạt")
                    e.Appearance.BackColor = Color.OrangeRed;
                else
                    e.Appearance.BackColor = Color.LightGreen;
            }
        }

        private void frmThongKeTotNghiep_V2_KeyDown(object sender, KeyEventArgs e)
        {
            switch (e.KeyData)
            {
                case Keys.F5:
                    bolIsRefresh = true;
                    LoadReferenceData();
                    btnSearch_Click(null, null);
                    break;
                case Keys.F6:
                    if (btnSave.Enabled)
                        btnSave_Click(sender, null);
                    break;
            }
        }

        #endregion
    }
}

