private bool HasTBC(DataRow drw)
{
    if (drw == null || drw["LearningSummary"] == null || drw["LearningSummary"] == DBNull.Value)
        return false;
    return drw["LearningSummary"].ToString().Trim() != "";
}

private void ReviewGraduation()
{
    if (!IsValidExamDate())
        return;

    if (dtbData == null || dtbData.Rows.Count == 0)
    {
        MessageManager.Warning("Không có dữ liệu để xét!");
        return;
    }

    int intReviewCount = 0;
    foreach (DataRow drw in dtbData.Rows)
    {
        if (!HasTBC(drw))
            continue;

        double dblTBC = Convert.ToDouble(drw["LearningSummary"]);
        bool bolPassed = dblTBC > 5;
        string strLearningLevel = drw["LearningLevel"].ToString();

        drw["SummaryLearningMark"] = dblTBC;
        drw["SummaryLearningLevel"] = strLearningLevel != "" ? (object)strLearningLevel : DBNull.Value;
        drw["GraduationRankingAverage"] = dblTBC;
        drw["GraduationExamAverage"] = dblTBC;

        if (bolPassed)
        {
            drw["GraduationLevel"] = strLearningLevel != "" ? (object)strLearningLevel : DBNull.Value;
            drw["ResultReview"] = 1;
        }
        else
        {
            drw["GraduationLevel"] = "Không đạt";
            drw["ResultReview"] = 0;
        }

        drw["ExamDateID"] = intExamDateID;
        drw["IsEdit"] = 1;
        intReviewCount++;
    }

    if (intReviewCount == 0)
    {
        MessageManager.Warning("Không có sinh viên nào có TBC để xét tốt nghiệp!");
        return;
    }

    ShowGraduationColumns(true);
    btnSave.Enabled = mnuItemSave.Enabled = true;
}

