private void CheckPermission()
{
    bool bolCanEdit = UserSession.HasPermission(PERMISSION_EDIT);
    btnXetTotNghiep.Enabled = bolCanEdit;
    btnSave.Enabled = mnuItemSave.Enabled = false;
    EnableSetGraduationButtons(false);
}

private void EnableSetGraduationButtons(bool bolEnabled)
{
    bool bolCanEdit = bolEnabled && UserSession.HasPermission(PERMISSION_EDIT);
    btnSetDecisionNo.Enabled = bolCanEdit;
    btnSetSigningdate.Enabled = bolCanEdit;
    btnSetYearID.Enabled = bolCanEdit;
    btnSetCerNo.Enabled = bolCanEdit;
    btnSetSavedCerNo.Enabled = bolCanEdit;
    btnSetCerIssued.Enabled = bolCanEdit;
}

private void SetValueToSelectedRows(string strFieldName, object objValue)
{
    if (dtbData == null)
        return;

    if (gvData.SelectedRowsCount > 0)
    {
        foreach (int i in gvData.GetSelectedRows())
        {
            DataRow drw = gvData.GetDataRow(i);
            if (drw != null)
            {
                drw[strFieldName] = objValue == null ? DBNull.Value : objValue;
                drw["IsEdit"] = 1;
            }
        }
    }
    else
    {
        foreach (DataRow drw in dtbData.Rows)
        {
            drw[strFieldName] = objValue == null ? DBNull.Value : objValue;
            drw["IsEdit"] = 1;
        }
    }
    btnSave.Enabled = mnuItemSave.Enabled = true;
}

