private void btnSetCerNo_Click(object sender, EventArgs e)
{
    if (txtStartCerNo.TextTrim != "")
    {
        int intLenOrder = txtStartCerNo.TextTrim.Length;
        int intStartOrder;
        if (int.TryParse(txtStartCerNo.TextTrim, out intStartOrder))
        {
            if (gvData.SelectedRowsCount > 0)
            {
                foreach (int i in gvData.GetSelectedRows())
                {
                    DataRow drw = gvData.GetDataRow(i);
                    if (drw != null && drw["GraduationLevel"].ToString() != "" && drw["GraduationLevel"].ToString() != "Không đạt")
                    {
                        string a = "0000000000" + intStartOrder.ToString();
                        drw["CerNo"] = txtPrefixCerNo.TextTrim + a.Substring(a.Length - intLenOrder);
                        drw["IsEdit"] = 1;
                        intStartOrder++;
                    }
                }
            }
            else
            {
                foreach (DataRow drw in dtbData.Rows)
                {
                    if (drw["GraduationLevel"].ToString() != "" && drw["GraduationLevel"].ToString() != "Không đạt")
                    {
                        string a = "0000000000" + intStartOrder.ToString();
                        drw["CerNo"] = txtPrefixCerNo.TextTrim + a.Substring(a.Length - intLenOrder);
                        drw["IsEdit"] = 1;
                        intStartOrder++;
                    }
                }
            }
            btnSave.Enabled = mnuItemSave.Enabled = true;
        }
        else
        {
            MessageManager.Warning("Bạn phải nhập số bắt đầu là số tự nhiên. Ví dụ 000001!");
            txtStartCerNo.Focus();
        }
    }
    else if (txtPrefixCerNo.TextTrim != "")
    {
        SetValueToSelectedRows("CerNo", txtPrefixCerNo.TextTrim);
    }
    else
    {
        MessageManager.Warning("Bạn phải nhập số hiệu bằng!");
        txtPrefixCerNo.Focus();
    }
}

