private const string GRADUATION_BAND = "TỐT NGHIỆP";
private const string HTML_TEMPLATE = "MauHTML/DanhSachDuDieuKienXetTotNghiep.htm";
private static readonly string[] SUBJECT_ID_LIST = new string[] { "H-NMVTH", "H-THDCCVVNN", "H-THDCDL", "H-THGTCB" };
private static readonly string[] MARK_FIELD_LIST = new string[] { "Mark_H_NMVTH", "Mark_H_THDCCVVNN", "Mark_H_THDCDL", "Mark_H_THGTCB" };

EnableSetGraduationButtons(HasGraduationData());
