        private int CountEligibleForPrint()
        {
            int intCount = 0;
            if (dtbData == null)
                return 0;

            foreach (DataRow drw in dtbData.Rows)
            {
                if (IsEligibleForPrint(drw))
                    intCount++;
            }
            return intCount;
        }

        private bool IsEligibleForPrint(DataRow drw)
        {
            if (!HasTBC(drw))
                return false;
            return Convert.ToDouble(drw["LearningSummary"]) > 5;
        }

        private string GetSubjectNameForPrint(string strSubjectID, string strDefault)
        {
            DataTable dtbSubject = SIM_SubjectService.Table;
            if (dtbSubject != null)
            {
                DataRow[] arrRow = dtbSubject.Select("SubjectID = '" + strSubjectID.Replace("'", "''") + "'");
                if (arrRow.Length > 0 && arrRow[0]["SubjectName"].ToString() != "")
                    return arrRow[0]["SubjectName"].ToString();
            }
            return strDefault;
        }

        private string GetPrintSubTitle()
        {
            string strTrainingType = "";
            string strCourseName = "";

            if (dtbData != null)
            {
                foreach (DataRow drw in dtbData.Rows)
                {
                    if (!IsEligibleForPrint(drw))
                        continue;

                    if (strTrainingType == "" && drw["TrainingType"].ToString() != "")
                        strTrainingType = drw["TrainingType"].ToString();
                    if (strCourseName == "" && drw["CourseName"].ToString() != "")
                        strCourseName = drw["CourseName"].ToString();

                    if (strTrainingType != "" && strCourseName != "")
                        break;
                }
            }

            int intYear = DateTime.Now.Year;
            if (lookupExamDate.EditValueDate != null)
                intYear = lookupExamDate.EditValueDate.Value.Year;

            if (strCourseName != "")
                strCourseName = "KHÓA " + strCourseName;

            return String.Format("HỆ ĐÀO TẠO {0} {1} NĂM {2}", strTrainingType.ToUpper(), strCourseName, intYear);
        }

        private string GetPrintLevel(DataRow drw)
        {
            if (drw["GraduationLevel"].ToString() != "" && drw["GraduationLevel"].ToString() != "Không đạt")
                return drw["GraduationLevel"].ToString();
            return drw["LearningLevel"].ToString();
        }

        private string GetHtmlValue(DataRow drw, string strColumn)
        {
            if (drw == null || !drw.Table.Columns.Contains(strColumn) || drw[strColumn] == DBNull.Value)
                return "&nbsp;";
            string strValue = drw[strColumn].ToString();
            if (strValue == "")
                return "&nbsp;";
            return strValue;
        }

        private string FormatMarkHTML(string strValue)
        {
            if (strValue == "&nbsp;" || strValue == "")
                return "&nbsp;";
            if (strValue == "-1" || strValue == "-1,0" || strValue == "-10")
                return "M";
            if (strValue == "110")
                return "Đ";
            if (strValue == "100")
                return "CĐ";
            return strValue;
        }

        private string DetailToHTML()
        {
            StringBuilder sbRows = new StringBuilder();
            DataView dv = dtbData.DefaultView;
            dv.Sort = "SpecialBranchName, ClassName, StudentCode";

            string strPrevBranch = "";
            int intGroupSTT = 0;
            int intGlobalSTT = 0;

            foreach (DataRowView drv in dv)
            {
                DataRow drw = drv.Row;
                if (!IsEligibleForPrint(drw))
                    continue;

                string strBranch = drw["SpecialBranchName"].ToString();
                if (strBranch != strPrevBranch)
                {
                    sbRows.Append("<tr class='group-row'><td colspan='14'>Nghề: ");
                    sbRows.Append(strBranch != "" ? strBranch : "&nbsp;");
                    sbRows.Append("</td></tr>");
                    strPrevBranch = strBranch;
                    intGroupSTT = 0;
                }

                intGlobalSTT++;
                intGroupSTT++;

                sbRows.Append("<tr>");
                sbRows.Append("<td>" + intGlobalSTT.ToString() + "</td>");
                sbRows.Append("<td>" + intGroupSTT.ToString() + "</td>");
                sbRows.Append("<td class='name first'>" + GetHtmlValue(drw, "StudentFirstName") + "</td>");
                sbRows.Append("<td class='name last'>" + GetHtmlValue(drw, "StudentLastName") + "</td>");
                sbRows.Append("<td>" + GetHtmlValue(drw, "BirthDateText") + "</td>");
                sbRows.Append("<td>" + GetHtmlValue(drw, "ClassName") + "</td>");

                for (int i = 0; i < MARK_FIELD_LIST.Length; i++)
                    sbRows.Append("<td>" + FormatMarkHTML(GetHtmlValue(drw, MARK_FIELD_LIST[i])) + "</td>");

                sbRows.Append("<td>" + FormatMarkHTML(GetHtmlValue(drw, "LearningSummary")) + "</td>");
                sbRows.Append("<td>" + GetHtmlValue(drw, "TBC_PassedPreview") + "</td>");
                sbRows.Append("<td>" + GetPrintLevel(drw) + "</td>");
                sbRows.Append("<td>&nbsp;</td>");
                sbRows.Append("</tr>");
            }

            return sbRows.ToString();
        }

        private void ExportToHTML()
        {
            if (!IsValidExamDate())
                return;

            if (dtbData == null || dtbData.Rows.Count <= 0)
            {
                MessageManager.Warning("Không có dữ liệu để in!");
                return;
            }

            if (CountEligibleForPrint() <= 0)
            {
                MessageManager.Warning("Không có học viên nào đủ điều kiện (TBC > 5) để in!");
                return;
            }

            string strFileContent = Libs.Files.ReadFile(HTML_TEMPLATE);
            if (strFileContent == null || strFileContent == "")
            {
                MessageManager.Warning("Không tìm thấy file mẫu HTML!");
                return;
            }

            string strHeader1 = SystemService.SYS_SettingService.GetStringValue("Report_Header_Text");
            string strHeader2 = SystemService.SYS_SettingService.GetStringValue("Report_Header2_Text");
            string strPlace = SystemService.SYS_SettingService.GetStringValue("Report_Place");
            if (strHeader1 == null || strHeader1 == "")
                strHeader1 = SystemService.SYS_SettingService.GetStringValue("Report_Header");
            if (strHeader2 == null)
                strHeader2 = "";
            if (strPlace == null || strPlace == "")
                strPlace = "TP. Hồ Chí Minh";

            DateTime dtmNow = DateTime.Now;
            string strPlaceDate = String.Format("{0}, ngày .... tháng .... năm {1}", strPlace, dtmNow.Year);
            string strExamDate = lookupExamDate.EditValueText;
            if (strExamDate == null || strExamDate == "")
                strExamDate = "&nbsp;";
            else
                strExamDate = "Kỳ tốt nghiệp: " + strExamDate;

            strFileContent = strFileContent.Replace("{HEADER_TEXT}", strHeader1);
            strFileContent = strFileContent.Replace("{HEADER2_TEXT}", strHeader2);
            strFileContent = strFileContent.Replace("{SUB_TITLE}", GetPrintSubTitle());
            strFileContent = strFileContent.Replace("{EXAM_DATE}", strExamDate);
            strFileContent = strFileContent.Replace("{PLACE_DATE}", strPlaceDate);
            strFileContent = strFileContent.Replace("{MD1_NAME}", GetSubjectNameForPrint(SUBJECT_ID_LIST[0], "MD1"));
            strFileContent = strFileContent.Replace("{MD2_NAME}", GetSubjectNameForPrint(SUBJECT_ID_LIST[1], "MD2"));
            strFileContent = strFileContent.Replace("{MD3_NAME}", GetSubjectNameForPrint(SUBJECT_ID_LIST[2], "MD3"));
            strFileContent = strFileContent.Replace("{MD4_NAME}", GetSubjectNameForPrint(SUBJECT_ID_LIST[3], "MD4"));
            strFileContent = strFileContent.Replace("{DETAIL}", DetailToHTML());
            strFileContent = strFileContent.Replace("{TOTAL}", CountEligibleForPrint().ToString());

            string strFileNameAs = "DanhSachDuDieuKienXetTotNghiep_" + intExamDateID.ToString() + ".htm";
            Libs.Files.WriteFile(strFileNameAs, strFileContent);
            System.Diagnostics.Process.Start(strFileNameAs);
        }

        #endregion

