private void UpdateBranchSummary(Hashtable hstSummary, DataRow drw)
{
    string strBranch = drw["SpecialBranchName"].ToString();
    if (strBranch == "")
        strBranch = " ";

    BranchPrintSummary item = hstSummary[strBranch] as BranchPrintSummary;
    if (item == null)
    {
        item = new BranchPrintSummary();
        item.BranchName = strBranch.Trim();
        hstSummary[strBranch] = item;
    }

    item.TotalStudent++;
    if (IsEligibleForPrint(drw))
    {
        item.GraduatedCount++;
        IncrementLevelCount(item, GetPrintLevel(drw));
    }
}

private void IncrementLevelCount(BranchPrintSummary item, string strLevel)
{
    if (strLevel == "Xuất sắc")
        item.XuatSac++;
    else if (strLevel == "Giỏi")
        item.Gioi++;
    else if (strLevel == "Khá")
        item.Kha++;
    else if (strLevel == "TB khá" || strLevel == "Trung bình khá")
        item.TBKha++;
    else if (strLevel == "Trung bình")
        item.TrungBinh++;
}

private string SummaryToHTML()
{
    Hashtable hstSummary = new Hashtable();
    foreach (DataRow drw in dtbData.Rows)
        UpdateBranchSummary(hstSummary, drw);

    string[] arrBranch = new string[hstSummary.Count];
    hstSummary.Keys.CopyTo(arrBranch, 0);
    Array.Sort(arrBranch);

    StringBuilder sbRows = new StringBuilder();
    int intTT = 0;
    int intTotalStudent = 0;
    int intTotalTN = 0;
    int intTotalXuatSac = 0;
    int intTotalGioi = 0;
    int intTotalKha = 0;
    int intTotalTBKha = 0;
    int intTotalTrungBinh = 0;

    foreach (string strBranch in arrBranch)
    {
        BranchPrintSummary item = (BranchPrintSummary)hstSummary[strBranch];
        intTT++;

        sbRows.Append("<tr>");
        sbRows.Append("<td>" + intTT.ToString() + "</td>");
        sbRows.Append("<td class='branch-name'>" + item.BranchName + "</td>");
        sbRows.Append("<td>" + item.TotalStudent.ToString() + "</td>");
        sbRows.Append("<td>" + item.GraduatedCount.ToString() + "</td>");
        sbRows.Append("<td>" + (item.XuatSac > 0 ? item.XuatSac.ToString() : "&nbsp;") + "</td>");
        sbRows.Append("<td>" + (item.Gioi > 0 ? item.Gioi.ToString() : "&nbsp;") + "</td>");
        sbRows.Append("<td>" + (item.Kha > 0 ? item.Kha.ToString() : "&nbsp;") + "</td>");
        sbRows.Append("<td>" + (item.TBKha > 0 ? item.TBKha.ToString() : "&nbsp;") + "</td>");
        sbRows.Append("<td>" + (item.TrungBinh > 0 ? item.TrungBinh.ToString() : "&nbsp;") + "</td>");
        sbRows.Append("</tr>");

        intTotalStudent += item.TotalStudent;
        intTotalTN += item.GraduatedCount;
        intTotalXuatSac += item.XuatSac;
        intTotalGioi += item.Gioi;
        intTotalKha += item.Kha;
        intTotalTBKha += item.TBKha;
        intTotalTrungBinh += item.TrungBinh;
    }

    sbRows.Append("<tr class='total-row'>");
    sbRows.Append("<td colspan='2'>Tổng cộng</td>");
    sbRows.Append("<td>" + intTotalStudent.ToString() + "</td>");
    sbRows.Append("<td>" + intTotalTN.ToString() + "</td>");
    sbRows.Append("<td>" + (intTotalXuatSac > 0 ? intTotalXuatSac.ToString() : "&nbsp;") + "</td>");
    sbRows.Append("<td>" + (intTotalGioi > 0 ? intTotalGioi.ToString() : "&nbsp;") + "</td>");
    sbRows.Append("<td>" + (intTotalKha > 0 ? intTotalKha.ToString() : "&nbsp;") + "</td>");
    sbRows.Append("<td>" + (intTotalTBKha > 0 ? intTotalTBKha.ToString() : "&nbsp;") + "</td>");
    sbRows.Append("<td>" + (intTotalTrungBinh > 0 ? intTotalTrungBinh.ToString() : "&nbsp;") + "</td>");
    sbRows.Append("</tr>");

    return sbRows.ToString();
}

