private void ExportToHTML(bool bolEligible)
{
    if (!IsValidExamDate())
        return;

    if (dtbData == null || dtbData.Rows.Count <= 0)
    {
        MessageManager.Warning("Không có dữ liệu để in!");
        return;
    }

    int intCount = CountForPrint(bolEligible);
    if (intCount <= 0)
    {
        if (bolEligible)
            MessageManager.Warning("Không có học viên nào đủ điều kiện (TBC > 5) để in!");
        else
            MessageManager.Warning("Không có học viên nào không đủ điều kiện để in!");
        return;
    }

    string strTemplate = bolEligible ? HTML_TEMPLATE_ELIGIBLE : HTML_TEMPLATE_NOT_ELIGIBLE;
    string strFileContent = Libs.Files.ReadFile(strTemplate);
    if (strFileContent == null || strFileContent == "")
    {
        MessageManager.Warning("Không tìm thấy file mẫu HTML!");
        return;
    }

    string strHeader1 = SystemService.SYS_SettingService.GetStringValue("Report_Header_Text");
    string strHeader2 = SystemService.SYS_SettingService.GetStringValue("Report_Header2_Text");
    string strPlace = SystemService.SYS_SettingService.GetStringValue("Report_Place");
    if (strHeader1 == null || strHeader1 == "")
        strHeader1 = SystemService.SYS_SettingService.GetStringValue("Report_Header");
    if (strHeader2 == null)
        strHeader2 = "";
    if (strPlace == null || strPlace == "")
        strPlace = "TP. Hồ Chí Minh";

    DateTime dtmNow = DateTime.Now;
    string strPlaceDate = String.Format("{0}, ngày .... tháng .... năm {1}", strPlace, dtmNow.Year);

    strFileContent = strFileContent.Replace("{HEADER_TEXT}", strHeader1);
    strFileContent = strFileContent.Replace("{HEADER2_TEXT}", strHeader2);
    strFileContent = strFileContent.Replace("{SUB_TITLE}", GetPrintSubTitle());
    strFileContent = strFileContent.Replace("{PLACE_DATE}", strPlaceDate);
    strFileContent = strFileContent.Replace("{MD1_NAME}", GetSubjectNameForPrint(SUBJECT_ID_LIST[0], "MD1"));
    strFileContent = strFileContent.Replace("{MD2_NAME}", GetSubjectNameForPrint(SUBJECT_ID_LIST[1], "MD2"));
    strFileContent = strFileContent.Replace("{MD3_NAME}", GetSubjectNameForPrint(SUBJECT_ID_LIST[2], "MD3"));
    strFileContent = strFileContent.Replace("{MD4_NAME}", GetSubjectNameForPrint(SUBJECT_ID_LIST[3], "MD4"));
    strFileContent = strFileContent.Replace("{DETAIL}", DetailToHTML(bolEligible));
    if (bolEligible)
        strFileContent = strFileContent.Replace("{SUMMARY}", SummaryToHTML());
    strFileContent = strFileContent.Replace("{TOTAL}", intCount.ToString());

    string strFileNameAs;
    if (bolEligible)
        strFileNameAs = "DanhSachDuDieuKienXetTotNghiep_" + intExamDateID.ToString() + ".htm";
    else
        strFileNameAs = "DanhSachKhongDuDieuKienXetTotNghiep_" + intExamDateID.ToString() + ".htm";

    Libs.Files.WriteFile(strFileNameAs, strFileContent);
    System.Diagnostics.Process.Start(strFileNameAs);
}

